#!/usr/bin/env bash
# run-test.sh [pve-updater args]
# Runs pve-updater.sh against the mock Proxmox environment generated by make-harness.sh.
# Nothing here touches a real system: pct/qm/pvesh/ssh/apt-get/docker/curl are all fakes.
#   bash tests/mock/make-harness.sh          # once (and after editing it)
#   bash tests/mock/run-test.sh --list
#   bash tests/mock/run-test.sh --dry-run
#   bash tests/mock/run-test.sh              # full run with failure injections
#   KEEP_SNAPS=1 bash tests/mock/run-test.sh --only 103 --no-host --no-ntfy
set -u
cd "$(dirname "$0")"
M="$PWD"
REPO="$(cd "$M/../.." && pwd)"
SB="$M/sandbox"
[ -x "$M/bin/pvesh" ] || { echo "run make-harness.sh first"; exit 1; }
rm -rf "$SB"; mkdir -p "$SB/hooks" "$SB/logs"
cp "$REPO/pve-updater.sh" "$SB/"
cp "$M/settings.conf" "$SB/settings.conf"
[ -f "$M/overrides.conf" ] && cp "$M/overrides.conf" "$SB/overrides.conf"
printf '%s\n' '#!/bin/sh' 'echo "post hook for n8n running"' > "$SB/hooks/119-post.sh"
printf '%s\n' '#!/bin/sh' 'echo "pre hook for ollama"; exit 3' > "$SB/hooks/114-pre.sh"
: > "$M/state/calls.log"; : > "$M/state/ntfy.log"; rm -f "$M/state/pvesh.count"
[ -n "${KEEP_SNAPS:-}" ] || rm -f "$M/state/snaps-"*
export PATH="$M/bin:$PATH" LANG=C.UTF-8 LC_ALL=C.UTF-8
bash "$SB/pve-updater.sh" "$@"
echo "=== exit code: $? ==="
echo "=== notification(s): $M/state/ntfy.log  |  run log: $SB/logs/latest.log ==="
